using UnityEngine;

namespace GauntletRun.Game
{
    /// <summary>Every material, mesh and clip the game uses; generated by the editor ProjectBuilder.</summary>
    public sealed class GameArt : ScriptableObject
    {
        [Header("Castle")]
        public Material Floor;
        public Material FloorDark;
        public Material Trim;
        public Material Wall;
        public Material WallDark;
        public Material Banner;
        public Material TorchFlame;
        public Material Wood;
        public Material WoodDark;
        public Material Iron;
        public Material Steel;

        [Header("Knight (tinted per skin at run time)")]
        public Material Armour;
        public Material Cloth;
        public Material Visor;

        [Header("Pickups")]
        public Material Gold;
        public Material Gem;
        public Material ShieldBlue;
        public Material MagnetRed;
        public Material DoublePurple;

        [Header("Particles and shadows")]
        public Material ParticleAdditive;
        public Material ParticleAlpha;
        public Material BlobShadow;

        [Header("Meshes (Unity's built-in shapes, referenced so builds include them)")]
        public Mesh CubeMesh;
        public Mesh SphereMesh;
        public Mesh CylinderMesh;
        public Mesh CapsuleMesh;
        public Mesh QuadMesh;

        [Header("Audio")]
        public AudioClip RunMusic;
        public AudioClip TitleMusic;
        public AudioClip Coin;
        public AudioClip GemSound;
        public AudioClip Jump;
        public AudioClip Land;
        public AudioClip Slide;
        public AudioClip Lane;
        public AudioClip PowerUp;
        public AudioClip ShieldBreak;
        public AudioClip Crash;
        public AudioClip Milestone;
        public AudioClip GameOver;
        public AudioClip NewBest;
        public AudioClip Buy;
        public AudioClip Click;
        public AudioClip Denied;
    }
}
